 background: #fff;
 border: 1px solid #e0e4e8;
 border-radius: 8px;
 overflow: hidden;
}

.submission-list table {
 width: 100%;
 border-collapse: collapse;
 font-size: 14px;
}

.submission-list th {
 text-align: left;
 padding: 12px 16px;
 background: #f5f7fa;
 color: #5a6877;
 font-weight: 600;
 text-transform: uppercase;
 font-size: 11px;
 letter-spacing: 0.04em;
 border-bottom: 1px solid #e0e4e8;
}

.submission-list td {
 padding: 12px 16px;
 border-bottom: 1px solid #eef1f4;
 color: #2c3e50;
}

.submission-list tbody tr {
 cursor: pointer;
 transition: background-color 0.12s ease;
}

.submission-list tbody tr:hover {
 background: #f0f6ff;
}

.submission-list tbody tr.selected {
 background: #e3f0ff;
 box-shadow: inset 3px 0 0 #2f6fed;
}

.submission-list .mono {
 font-family: "SFMono-Regular", Consolas, monospace;
 font-weight: 600;
 color: #2f6fed;
}

.subscription-badge {
 display: inline-block;
 padding: 2px 10px;
 border-radius: 12px;
 background: #eef1f4;
 color: #5a6877;
 font-size: 12px;
 font-weight: 600;
}

.no-submissions {
 padding: 48px;
 text-align: center;
 color: #8a96a3;
 background: #fff;
 border: 1px dashed #d0d7de;
 border-radius: 8px;
}',"style"),insertStyle(".form-overlay {
 position: fixed;
 inset: 0;
 background: rgba(20, 28, 38, 0.45);
 display: flex;
 align-items: flex-start;
 justify-content: center;
 padding: 48px 16px;
 z-index: 100;
}

.form-container {
 background: #fff;
 border-radius: 10px;
 width: 100%;
 max-width: 560px;
 box-shadow: 0 12px 40px rgba(0, 0, 0, 0.2);
 overflow: hidden;
}

.form-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: 20px 24px;
 border-bottom: 1px solid #eef1f4;
}

.form-header h2 {
 margin: 0;
 font-size: 18px;
 color: #1f2d3d;
}

.close-button {
 background: none;
 border: none;
 font-size: 24px;
 line-height: 1;
 color: #8a96a3;
 cursor: pointer;
}

.close-button:hover {
 color: #1f2d3d;
}

.form-hint {
 margin: 0;
 padding: 14px 24px;
 background: #f0f6ff;
 color: #3a5a8c;
 font-size: 13px;
}

.form-container form {
 padding: 20px 24px 24px;
}

.form-row {
 display: flex;
 gap: 16px;
}

.form-row .form-group {
 flex: 1;
}

.form-group {
 margin-bottom: 16px;
}

.form-group label {
 display: block;
 margin-bottom: 6px;
 font-size: 13px;
 font-weight: 600;
 color: #5a6877;
}

.form-group input,
.form-group select {
 width: 100%;
 box-sizing: border-box;
 padding: 9px 12px;
 border: 1px solid #d0d7de;
 border-radius: 6px;
 font-size: 14px;
 color: #1f2d3d;
 background: #fff;
}

.form-group input:focus,
.form-group select:focus {
 outline: none;
 border-color: #2f6fed;
 box-shadow: 0 0 0 3px rgba(47, 111, 237, 0.15);
}

.form-actions {
 display: flex;
 justify-content: flex-end;
 gap: 12px;
 margin-top: 8px;
}

.cancel-button,
.submit-button {
 padding: 9px 18px;
 border-radius: 6px;
 font-size: 14px;
 font-weight: 600;
 cursor: pointer;
 border: 1px solid transparent;
}

.cancel-button {
 background: #fff;
 border-color: #d0d7de;
 color: #5a6877;
}

.cancel-button:hover {
 background: #f5f7fa;
}

.submit-button {
 background: #2f6fed;
 color: #fff;
}

.submit-button:hover {
 background: #2559c9;
