 background: #fff;
 border: 1px solid #e0e4e8;
 border-radius: 8px;
 padding: 20px;
 position: sticky;
 top: 20px;
 align-self: start;
}

.detail-header {
 display: flex;
 justify-content: space-between;
 align-items: flex-start;
 border-bottom: 1px solid #eef1f4;
 padding-bottom: 14px;
 margin-bottom: 14px;
}

.detail-number {
 font-family: "SFMono-Regular", Consolas, monospace;
 font-size: 12px;
 font-weight: 600;
 color: #2f6fed;
}

.detail-header h2 {
 margin: 4px 0 0;
 font-size: 17px;
 color: #1f2d3d;
}

.detail-meta {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 12px;
 margin: 0 0 20px;
}

.detail-meta dt {
 font-size: 11px;
 text-transform: uppercase;
 letter-spacing: 0.04em;
 color: #8a96a3;
 font-weight: 600;
}

.detail-meta dd {
 margin: 2px 0 0;
 font-size: 14px;
 color: #2c3e50;
}

.section-title {
 font-size: 13px;
 text-transform: uppercase;
 letter-spacing: 0.04em;
 color: #5a6877;
 margin: 0 0 12px;
}

.orch-banner {
 display: flex;
 flex-direction: column;
 gap: 2px;
 background: #f0f6ff;
 border: 1px solid #d6e4ff;
 border-radius: 6px;
 padding: 10px 14px;
 margin-bottom: 16px;
 font-size: 14px;
 color: #2c3e50;
}

.orch-banner--empty {
 background: #fff8e6;
 border-color: #ffe2a8;
 color: #8a6d2f;
 font-size: 13px;
}

.case-groups {
 display: flex;
 flex-direction: column;
 gap: 12px;
}

.case-group {
 border: 1px solid #eef1f4;
 border-radius: 6px;
 overflow: hidden;
}

.case-group-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 background: #f5f7fa;
 padding: 8px 14px;
 font-size: 13px;
 font-weight: 600;
 color: #5a6877;
}

.case-count {
 background: #5a6877;
 color: #fff;
 border-radius: 10px;
 min-width: 20px;
 height: 20px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 font-size: 11px;
 padding: 0 6px;
}

.case-row {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: 8px 14px;
 border-top: 1px solid #eef1f4;
}

.case-empty {
 padding: 8px 14px;
 color: #b0b9c2;
 font-size: 13px;
 font-style: italic;
}

.mono {
 font-family: "SFMono-Regular", Consolas, monospace;
 font-size: 13px;
 font-weight: 600;
 color: #2f6fed;
}

.result-badge {
 font-size: 12px;
 font-weight: 600;
 padding: 2px 10px;
 border-radius: 12px;
 background: #eef1f4;
 color: #5a6877;
 text-transform: capitalize;
}

/* Status tones shared across clearance / risk / quote results */
.tone-pending,
.tone-draft {
 background: #eef1f4;
 color: #5a6877;
}

.tone-cleared,
.tone-low,
.tone-bound,
.tone-quoted {
 background: #e3f7ea;
 color: #1f7a44;
}

.tone-flagged,
.tone-high,
.tone-declined {
 background: #fdeaea;
 color: #b3261e;
}

.tone-medium {
 background: #fff4e0;
 color: #97631a;
}

.tone-critical {
 background: #b3261e;
 color: #fff;
}

.detail-loading,
.detail-error {
 padding: 16px;
 text-align: center;
 font-size: 14px;
 border-radius: 6px;
}

.detail-loading {
 color: #8a96a3;
}

.detail-error {
 background: #fdeaea;
 color: #b3261e;
